parameters.jsCode:
const items = $input.all();
const outputs = [];

for (const item of items) {
  const binaries = item.binary || {};

  for (const [key, binary] of Object.entries(binaries)) {
    outputs.push({
      json: {
        attachmentKey: key,
        fileName: binary.fileName,
        mimeType: binary.mimeType,
        fileSize: binary.fileSize,
      },
      binary: {
        file: binary // standardize binary key as `file`
      }
    });
  }
}

return outputs;

